<script setup lang="ts">
import {localize} from './localization';

import {computed,ref} from 'vue';
import {useSession} from './store';
const props=defineProps<{language:'zh'|'en'}>(),store=useSession(),zh=computed(()=>props.language==='zh');
async function cancelProjection(){const p=store.data.project;if(p)await window.fpcad.cancelSurface(p.id,p.revision);}
const inferenceSource=ref(''),inferenceMode=ref<'extend'|'symmetry'>('extend'),inferenceDistance=ref(100),inferencePlane=ref(0),inferring=ref(false);
async function infer(){const p=store.data.project;if(!p)return;inferring.value=true;try{await store.run(()=>window.fpcad.inferMarking(p.id,p.revision,inferenceSource.value,inferenceMode.value,inferenceDistance.value,inferencePlane.value));}finally{inferring.value=false;}}
</script>
<template><details v-if="store.data.project?.markings?.some(m=>!m.inference)" class="inference-panel"><summary>{{zh?'侧面花纹补全':localize('Complete side markings')}}</summary><p>{{zh?'沿相邻面延伸仅填充没有花纹记录的整面，距离为相邻面中心路径近似。对称仅支持关于指定 X 平面的精确网格对应。原有区域不覆盖，推断结果在三维/裁版中显示，核对并确认后才可制造导出；复杂边界请手绘。':localize('Extension fills only faces without marking records using approximate adjacent-center distance. Symmetry requires exact mesh correspondence about an X plane. Existing regions stay intact. Inspect inferred results in both views and approve before exporting; draw complex boundaries manually.')}}</p><div class="reference-controls"><select v-model="inferenceSource" aria-label="Inference source"><option value="">{{zh?'选择来源花纹':localize('Choose source marking')}}</option><option v-for="m in store.data.project?.markings?.filter(m=>!m.inference)??[]" :key="m.id" :value="m.id">{{m.name}}</option></select><select v-model="inferenceMode" aria-label="Inference mode"><option value="extend">{{zh?'沿邻面延伸':localize('Extend adjacent faces')}}</option><option value="symmetry">{{zh?'左右对称':localize('Mirror about X')}}</option></select><label v-if="inferenceMode==='extend'">{{zh?'延伸距离 mm':localize('Extension distance mm')}}<input v-model.number="inferenceDistance" aria-label="Inference distance" type="number" min=".01" max="10000"></label><label v-else>{{zh?'对称平面 X mm':localize('Symmetry plane X mm')}}<input v-model.number="inferencePlane" aria-label="Symmetry plane" type="number"></label><button :disabled="store.busy||!inferenceSource" @click="infer">{{zh?'生成待审核补全':localize('Generate completion for review')}}</button><button v-if="inferring" @click="cancelProjection">{{zh?'取消计算':localize('Cancel calculation')}}</button></div></details></template>
<style scoped>p{font-size:11px;line-height:1.7}label{display:block;font-size:11px;margin:10px 0}button{width:100%;white-space:normal;margin-block:5px}</style>
